\begin{aligned}
\mathsf{Ax}_{Inc}^{H}={}&
\{\forall a:\mathsf{Pt}\forall b:\mathsf{Pt}(a\ne_{\mathsf{Pt}} b\to
\exists l:\mathsf{Ln}(a\in l\wedge b\in l\wedge
\forall m:\mathsf{Ln}((a\in m\wedge b\in m)\to m\doteq_{\mathsf{Ln}}l)))\}\\
&\cup\{\forall a:\mathsf{Pt}\forall b:\mathsf{Pt}\forall c:\mathsf{Pt}(NonCol(a,b,c)\to
\exists\pi:\mathsf{Pl}(a\in\pi\wedge b\in\pi\wedge c\in\pi\\
&\hspace{34mm}\wedge\forall\rho:\mathsf{Pl}((a\in\rho\wedge b\in\rho\wedge c\in\rho)
\to\rho\doteq_{\mathsf{Pl}}\pi)))\}\\
&\cup\{\forall l:\mathsf{Ln}\forall\pi:\mathsf{Pl}
((\exists a:\mathsf{Pt}\exists b:\mathsf{Pt}(a\ne_{\mathsf{Pt}}b\wedge a\in l\wedge b\in l
\wedge a\in\pi\wedge b\in\pi))\to LineIn(l,\pi))\}\\
&\cup\{\forall l:\mathsf{Ln}\exists a:\mathsf{Pt}\exists b:\mathsf{Pt}
(a\ne_{\mathsf{Pt}}b\wedge a\in l\wedge b\in l)\}\\
&\cup\{\forall\pi:\mathsf{Pl}\exists a:\mathsf{Pt}\exists b:\mathsf{Pt}\exists c:\mathsf{Pt}
(NonCol(a,b,c)\wedge a\in\pi\wedge b\in\pi\wedge c\in\pi)\}\\
&\cup\{\exists a:\mathsf{Pt}\exists b:\mathsf{Pt}\exists c:\mathsf{Pt}\exists d:\mathsf{Pt}
\neg Coplanar(a,b,c,d)\}.
\end{aligned}

\begin{aligned}
\mathsf{Ax}_{Cong}^{H}={}&
\{\forall a,b:\mathsf{Pt}\,SC(a,b,a,b)\}
\cup\{\forall a,b,c,d:\mathsf{Pt}(SC(a,b,c,d)\to SC(c,d,a,b))\}\\
&\cup\{\forall a,b,c,d,e,f:\mathsf{Pt}
((SC(a,b,c,d)\wedge SC(c,d,e,f))\to SC(a,b,e,f))\}\\
&\cup\{\forall a,b,c:\mathsf{Pt}(SC(a,b,c,c)\to a\doteq_{\mathsf{Pt}}b)\}\\
&\cup\{\forall a,b,c,d:\mathsf{Pt}(c\ne_{\mathsf{Pt}}d\to
\exists e:\mathsf{Pt}(Ray(c,d,e)\wedge SC(a,b,c,e)\\
&\hspace{34mm}\wedge\forall e':\mathsf{Pt}((Ray(c,d,e')\wedge SC(a,b,c,e'))
\to e'\doteq_{\mathsf{Pt}}e)))\}\\
&\cup\{\forall a,b,c:\mathsf{Pt}\,AC(a,b,c,a,b,c)\}\\
&\cup\{\forall a,b,c,d,e,f:\mathsf{Pt}(AC(a,b,c,d,e,f)\to AC(d,e,f,a,b,c))\}\\
&\cup\{\forall a,b,c,d,e,f,g,h,i:\mathsf{Pt}
((AC(a,b,c,d,e,f)\wedge AC(d,e,f,g,h,i))\to AC(a,b,c,g,h,i))\}\\
&\cup\{\forall a,b,c,a',b',c':\mathsf{Pt}
((SC(a,b,a',b')\wedge SC(a,c,a',c')\wedge AC(b,a,c,b',a',c'))
\to SC(b,c,b',c'))\}.
\end{aligned}

\mathsf{Ax}_{Par}^{H}=\{\forall l:\mathsf{Ln}\forall p:\mathsf{Pt}
(\neg(p\in l)\to\exists m:\mathsf{Ln}(p\in m\wedge Par(l,m)
\wedge\forall n:\mathsf{Ln}((p\in n\wedge Par(l,n))\to n\doteq_{\mathsf{Ln}}m)))\}.
